      "--commits-file", commitsFile,
      "--changelog", join(dir, "CHANGELOG.md"),
    ]);
    expect(code).toBe(0);
    expect(stdout).toContain("NEW_VERSION=2.0.0");
    expect(stdout).toContain("BUMP=none");
  });
});

